quests[7676] = { id = 7676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatz für Euren weißen Roboschreiter" }
quests[7677] = { id = 7677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austausch Eures Schimmels" }
quests[7678] = { id = 7678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austausch Eures Palominos" }
quests[7701] = { id = 7701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Maltorius", description = "Auf Anordnung seiner Eminenz, Aufseher Schlickfaust, des Agenten der Thoriumbruderschaft und gleichzeitig neu angeheuerten Kommandanten der Schlackengrubentruppe der Dunkeleisenzwerge des Kessels, soll Aufseher Maltorius getötet und sein Kopf als Beweis für die Tat erbracht werden. \n\nTrefft Euch mit dem Hauptmann des Ausgucks, Lolo Langhieb, wegen der Belohnung für diese schwierige Aufgabe.", sourceObjective = "Tief in der Schlackengrube des Kessels in der Sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden. \n\nTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Hauptmann des Ausgucks Lolo Langhieb in der Sengenden Schlucht für eine Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[7702] = { id = 7702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie mit Schlafentzug", description = "Wenn wir die Produktivität der Dunkeleisenzwerge in der Schlackengrube behindern wollen, müssen wir sie dort treffen wo es am meisten schmerzt. .\n\nEs ist eine wenig bekannte Tatsache, aber Zwerge müssen sich ausruhen, besonders die Dunkeleisenzwerge! Die brauchen viel Ruhe!\n\nNun frage ich Euch, wie können sie ohne Kissen schlafen? Genau, {name}, sie können es nicht. Das ist der Grund, aus dem Ihr euch in die Schlackengrube begeben müsst, um ihre Kissen zu stehlen.", sourceObjective = "Tief in der Schlackengrube des Kessels, findet Ihr die Schlafräume der Dunkeleisenzwerge.\n\nFindet diese Schlafkammern und stibitzt 20 Dunkeleisenkissen. Kehrt dann zu Evonice Rußraucher in der Sengenden Schlucht, wenn Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7703] = { id = 7703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elfen, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.\n\nKrombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[7704] = { id = 7704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie groß das ist!", description = "Ja, ja… wenn das nicht eine Überraschung ist. Das Zimmermädchen besaß ein riesiges verziertes Kissen und nun ist es Eures. Geht zu Evonice Rußraucher, sie kann es nicht erwarten dieses Kissen zu bekommen und mit ihren fettigen Händen zu begrapschen. Bringt es ihr und schaut ob sie Euch dafür auch irgendwie für die Mühen entlohnt.", sourceObjective = "Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Rußraucher in der Sengenden Schlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[7721] = { id = 7721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff fürs Schrumpfen", description = "Wenn ich gegen mein besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern. Verdammt sei der unkontrollierte Elementalismus, sage ich!\n\nGlücklicherweise stellen die Elementare eine ideale Quelle reiner Kraft für meinen Ultraschrumpfer dar – insofern, gebt ihnen Saures! Wenn Ihr dies allerdings tut, bringt mir doch bitte auch ein paar Elementarkerne.", sourceObjective = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks.", sourceObjectiveStatus = "unverified-source-field" }
quests[7722] = { id = 7722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Fluxus?!", description = "Als dieser Verräter Maltorius unseren Klan verließ, verließ er ihn mit etwas viel wertvollerem als einem makellosen Arkankristall: Unserem Rezept für den feurigen Fluxus! Ich verwette mein letztes Hemd, dass das ein Teil der Absprache für seine Beförderung innerhalb der Dunkeleisenzwerge war.\n\nBringt unsere geheimen Pläne zurück, {name}. Ich bin mir sicher, dass sie in der Nähe von Maltorius, tief in der Schlackengrube sind.", sourceObjective = "Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der Sengenden Schlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[7723] = { id = 7723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt seien diese fetten Finger", description = "Unglücklicherweise kann ich nicht mehr so austeilen, wie es früher einmal konnte, dank meines Problems hier, meine fetten Finger. Das Klima hier draußen und dazu der geringe Luftdruck lässt meine Finger einfach aufquellen. Die sehen schon aus wie gigantische Thelsamarer Blutwürste...\n\nDu wirst meine Aufträge ausführen müssen. \n\nAls erstes steht auf meiner Liste: Prügelt das letzte bisschen Leben aus den Schweren Kriegsgolems in der Schlucht. Leg los!", sourceObjective = "Hansel Bleihand möchte, dass Ihr 20 Schwere Kriegsgolems tötet. \n\nDie Schweren Kriegsgolems wandern in der Gegend um den Kessel in der Sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7724] = { id = 7724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feurige Bedrohung!", description = "Würd' ich's nicht besser wissen, würd' ich behaupten, dass jedes Mal, wenn der alte Hansel sich endlich 'mal ein wenig entspannen möchte, ihm die höheren Mächte einen weiteren Auftrag erteilen.\n\nDas macht mich echt nachdenklich, wisst Ihr? Ihr wisst doch was ich meine, oder?\n\nDie Lavaspinnen hier in der Gegend, haben in der letzten Zeit einen ganz schönen Krawall verursacht. Schlickfaust meint, dass sie Feuer spucken würden, und zwar aus ihren... Ähm, ja, jedenfalls beunruhigt so etwas die Kinder.\n\nSchätze wir werden sie erledigen müssen. Genau genommen wird das dein Job sein.", sourceObjective = "Hansel Bleihand möchte, dass Ihr 20 große Lavaspinnen in der Sengenden Schlucht tötet. \n\nDie großen Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der Sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7725] = { id = 7725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wieder unter den geschrumpften Riesen", description = "Ich weiß, dass Ihr schon Überreste für mich gesammelt habt... aber solltet Ihr auf der Suche nach einer zusätzlichen Aufgabe sein, könnte ich immer noch einige Überreste gebrauchen.\n\nIch kann zwar nicht genauso viel als Belohnung bieten wie zuvor, aber dafür wäre ich mehr als glücklich ein gutes Wort über Euch unter meinen Goblinfreunden verlauten zu lassen. Unter denen zumindest, die über Ohren verfügen. .\n\nGlaubt mir, <Herr/Frau> wenn ich Euch sage, dass diese Goblins über wirklich ziemliche große Ohren verfügen.", sourceObjective = "Benutzt Zorbins Ultraschrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpfüberreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin von Schiller am Dock der Vergessenen Küste in Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[7726] = { id = 7726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Treibstoff fürs Schrumpfen", description = "Mehr Arbeit, sagt Ihr? Hat meine heroische Aufgabe des Schleimsammelns von den Elementaren nicht Euren Durst nach Abenteuern gelöscht? Vielleicht wird etwas mehr davon den unerschöpflichen Brunnen, der Ihr seid, füllen...\n\nOk, Melodramatik beiseite, ich bräuchte noch ein paar Wasserelementarkerne. Ich versuche verzweifelt, einen Laden hier aufzumachen, also wird der Lohn leider nicht groß sein... aber ich verspreche, dass ich jedem in Hörweite erzählen werde, dass Ihr mir geholfen habt. Vertraut mir – Ich kenne eine Menge Leute im Kartell!", sourceObjective = "Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks.", sourceObjectiveStatus = "unverified-source-field" }
quests[7727] = { id = 7727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendosaurier? Was-auch-immer-Saurier?", description = "Meine Zehen, <Kumpel/Mädel>. Meine verdammten Zehen sind angeschwollen. Wie soll ich irgendetwas jagen können, wenn meine Füße mich schon umbringen? Darum brauche ich Eure Hilfe.\n\nSkrange und Burninate haben mich beauftragt, diese Dinger zur Strecke zu bringen, damit sie weitere Expeditionen in die Lavabecken der Schlackengrube schicken können. Anscheinend stehen einige Incendosaurier oder so was in der Art diesem Vorhaben im Weg... Wollt Ihr hier Wurzeln schlagen oder habt Ihr die Incendosaurier schon erledigt?", sourceObjective = "Hansel Bleihand möchte, dass Ihr 20 Incendosaurier tötet.\n\nDie Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der Sengenden Schlucht.\n\nSobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Bleihand in der Sengenden Schlucht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7728] = { id = 7728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESTOHLEN: Schmiedewindform und ein Ausguckhandfernrohr", description = "Folgende Gegenstände wurden gestohlen:\n\nEine Schmiedewindform.\n\nEin Ausguckhandfernrohr.\n\nEs wurde eine Belohnung für das Zurückbringen der gestohlenen Gegenstände ausgesetzt.\n\nDie Thoriumbruderschaft ist sich sicher, dass diese Gegenstände von skrupellosen und neidischen Dunkeleisenzwergen aus der Sengenden Schlucht entwendet wurden.\n\nDas fragliche Fernrohr ist ein hervorragendes Werkzeug für Spähposten und die Schmiedeform ist schlicht unersetzlich. \n\nSolltet Ihr einen der vermissten Gegenstände finden, bringt sie zu Skrange.", sourceObjective = "Sucht die Schmiedewindform und das Ausguckhandfernrohr. Bringt diese Gegenstände zu Zuchtmeister Skrange in der Sengenden Schlucht.\n\nDie einzigen Informationen die Ihr habt sind: Die Schmiedewindform ist ein Schmiedewerkzeug welches von Schmieden verwendet wird und das Ausguckhandfernrohr ist ein unverzichtbares Werkzeug für Spähposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[7729] = { id = 7729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "STELLE ZU VERGEBEN: Erledige die Konkurrenz", description = "Zuchtmeister Skrange sucht einige fähige Männer und Frauen, um seiner Konkurrenz in der Sengenden Schlucht ein wenig einzuheizen.\n\nInteressierte Bewerber sollten zur Sengenden Schlucht reisen und jeden Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge erschlagen, der ihnen über den Weg läuft.\n\nMeldet Euch bei Zuchtmeister Skrange, wenn Eure Kleidung ausreichend mit Blut getränkt wurde.\n\nIhr werdet schon sehen, wann sie blutig genug ist, also spart Euch jegliche Rückfragen.", sourceObjective = "Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Skrange zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7730] = { id = 7730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Schenken wir unseren angesammelten Erkundungen Glauben, so gehört der Gegner südlich der Gnolle einer insektenartigen Rasse an. Offen gesagt spielt es keine Rolle, solange sie lebendig sind. Wenn sie die Gnolle gegen uns aufhetzen, dann sind sie eine mindestens genauso große Bedrohung - wenn nicht sogar eine größere - als die Gnolle selbst.\n\nDringt tief in das Gebiet vor, in dem die Insekten der Zukk'ash hausen; auch bekannt als Gewundene Tiefe. Dezimiert ihre Anzahl, berichtet mir von Euren Entdeckungen und bringt ihre Knochenpanzer als Beweis Eurer Taten zurück.", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[7731] = { id = 7731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Einer unserer Späher berichtete, dass er während seiner Beobachtungen der Gewundenen Tiefe ein riesiges Insekt – viel größer als die anderen gesichteten Insekten – gesehen habe, das durch das verschlungene Gelände umherstreifte. Es ist nicht nur größer, es scheint auch eine Art Aura abzusondern, was die anderen Insekten nicht tun. Wir haben ihm einen Namen gegeben – Zornstachel.\n\nEine Untersuchung der Innereien dieser Bestie wäre von unschätzbarem Wert, solange wir nach dem besten Weg suchen, um mit dieser Bedrohung fertigzuwerden. Schneidet seine Sekretionsdrüsen heraus und bringt sie sofort zu mir zurück!", sourceObjective = "Besiegt Zornstachel in der Gewundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7732] = { id = 7732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über die Zukk'ash", description = "Ihr habt mehr als richtig gehandelt, indem Ihr Euch der Bedrohung, die die Insekten der Zukk'ash für das Camp Mojache darstellen, zugewandt habt. Die Gefahr, die von ihnen ausgeht, ist noch lange nicht vorüber. Deshalb würde ich Euch im Namen der Horde gerne um die Erledigung eines letzten Auftrags bitten.\n\nDies hier sind Aufzeichnungen, die alle Informationen, die wir über diese Zukk'ash erhalten haben, detailliert beinhalten. Ich möchte, dass Ihr sie zu Zilzibin Tomtom in der Gasse in Orgrimmar bringt. Er ist ein Experte, wenn es um fremde Kreaturen wie diese geht; ich hoffe, er kann etwas mit den von uns gewonnenen Erkenntnissen anfangen.", sourceObjective = "Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Tomtom. Er wohnt in der Gasse von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[7733] = { id = 7733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ob Ihr es glaubt oder nicht, ich habe eine noch viel bessere Quelle für Yetibälge entdeckt! Im nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere Yetis. Diese Wesen sind noch um einiges stärker, als jene mit denen Ihr schon zu tun hattet. Also, wenn Ihr eine größere Herausforderung sucht, sind diese Biester genau das Richtige für Euch.\n\nIch werde Euch großzügig entlohnen, wenn Ihr mir 10 Wutschrammyetibälge bringt!", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 10 Wutschrammyetibälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[7734] = { id = 7734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Qualität", description = "Ob Ihr es glaubt oder nicht, ich habe eine noch viel bessere Quelle für Yetibälge entdeckt! Im nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere Yetis. Diese Wesen sind noch um einiges stärker, als jene mit denen Ihr schon zu tun hattet. Also, wenn Ihr eine größere Herausforderung sucht, sind diese Biester genau das Richtige für Euch.\n\nIch werde Euch großzügig entlohnen, wenn Ihr mir 10 Wutschrammyetibälge bringt!", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas 10 Wutschrammyetibälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[7735] = { id = 7735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Yetibalg", description = "Ihr habt einen makellosen Yetibalg gefunden, der besonders dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Pratt McGrubben in der Mondfederfeste mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste den makellosen Yetibalg.", sourceObjectiveStatus = "unverified-source-field" }
quests[7736] = { id = 7736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub an feurigem Fluxus: Königsblut" }
quests[7737] = { id = 7737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Anerkennung erlangen", progress = "Ihr habt Euch erfolgreich in der Hierarchie der Bruderschaft hochgearbeitet, {race}. Wir haben begonnen, Euch mit Wohlwollen zu betrachten. Eine respektable Leistung!\n\nWenn Ihr Euch weiteren Respekt und Arbeit verschaffen wollt, hört genau zu.\n\nWir können den feurigen Fluxus noch weiter veredeln, indem wir ihm simple Dunkeleisenrückstände hinzufügen. Diese Rückstände sind hauptsächlich in den Schwarzfelstiefen zu finden.\n\nBringt mir alle Dunkeleisenrückstände, die Ihr finden könnt!", completion = "Je mehr Dunkeleisenrückstände, desto besser!" }
quests[7738] = { id = 7738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekter Yetibalg", description = "Ihr habt einen Yetibalg gefunden, der beinahe perfekt scheint. Euch fällt schnell auf, dass dieser außergewöhnlich dick und widerstandsfähig ist - sogar robuster als die Yetibälge aus der Wutschrammfeste.\n\nIn Anbetracht der Tatsache, dass Jangdor Flinkschreiter im Camp Mojache mit Yetibälgen handelt, dürfte ihn dieser Fund besonders interessieren.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas den perfekten Yetibalg.", sourceObjectiveStatus = "unverified-source-field" }
quests[7761] = { id = 7761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfausts Befehl", description = "Schwachkopf,\n\nich habe Euch immer für unfähig gehalten, Fremde daran zu hindern, den Hort unseres Herrn zu betreten. Für den sehr wahrscheinlichen Fall Eures Todes hat diese Kugel einen eingebauten Sicherheitsmechanismus, der verhindert, dass sich Außenstehende direkt in den Pechschwingenhort teleportieren können.\n\nNur diejenigen, denen das Mal von Drakkisath in die Handfläche eingebrannt wurde, können die Kugel überhaupt benutzen. Glücklicherweise ist Drakkisath nicht einmal ansatzweise so inkompetent wie Ihr, Rüstmeister. Er selbst bewacht das Brandzeichen!\n\nKriegshäuptling Rend Schwarzfaust\n\nP.S. Verbrennt diesen Brief, Idiot!", sourceObjective = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.\n\nDem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7781] = { id = 7781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher des Schwarzfels", description = "Ihr spürt, wie längst vergessene Gefühle in Euch aufflammen. Der willkommene Schmerz des Sieges hallt durch Euer Innerstes. Euch zu Füßen liegt der vom Kampf gezeichnete, gigantische Kopf von Nefarian. Bringt ihn der Großadmiralin in Vertretung des Königs, <großer Held/große Heldin>!", sourceObjective = "Bringt den Kopf von Nefarian zu Großadmiralin Jes-Tereth in Sturmwind.", progress = "Unfassbar!", completion = "Seid Ihr Euch gewahr, was Ihr da vollbracht habt, {name}? Dieser Tag wird in die Geschichte eingehen! Einen solchen Sieg hat die Allianz schon seit Jahrzehnten nicht mehr gesehen - falls überhaupt jemals!", sourceObjectiveStatus = "unverified-source-field" }
quests[7782] = { id = 7782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher des Schwarzfels", description = "Begebt Euch in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", sourceObjective = "Reist nach Sturmwind in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", completion = "<Feldmarschall Afrasiabi verbeugt sich.>\n\nSucht Euch eine Belohnung aus und lasst die Feierlichkeiten beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7783] = { id = 7783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher des Schwarzfels", description = "Ihr spürt, wie längst vergessene Gefühle in Euch aufflammen. Der willkommene Schmerz des Sieges hallt durch Euer Innerstes. Euch zu Füßen liegt der vom Kampf gezeichnete, gigantische Kopf von Nefarian. Bringt ihn zu Etrigg, dem Berater des Kriegshäuptlings, <großer Held/große Heldin>!", sourceObjective = "Bringt den Kopf von Nefarian zu Etrigg in Orgrimmar.", progress = "Ich wünschte, ich hätte den Gesichtsausdruck der Bestie sehen können, als Ihr ihr den Todesstoß versetzt habt!", completion = "Und wieder habt Ihr die Horde geehrt, {name}. Todesschwinges Sohn ist tot.\n\nDas wird dem Bösen nicht gefallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7784] = { id = 7784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herrscher des Schwarzfels", description = "Sucht Oberanführer Natoj im Tal der Stärke auf.", sourceObjective = "Sprecht mit Oberanführer Natoj in Orgrimmar. Er erwartet Euch im Tal der Stärke.", completion = "Wählt Eure Belohnung. Ich werd' den Kopf der Bestie für alle gut sichtbar anbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7785] = { id = 7785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Gefäßes", description = "Untersucht das Gefäß der Wiedergeburt, Sterblicher. Mit seiner Hilfe soll der Windsucher wieder auferstehen!", sourceObjective = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.", progress = "Werdet Ihr ihn aus seiner ewigen Gefangenschaft befreien?", completion = "Möget auf Euren Wegen von Schutz begleitet werden. Möge der Meister Eure Bemühungen segnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7786] = { id = 7786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donneraan der Windsucher", description = "Ich habe Euch alles gesagt was ich weiß, {name}. Es ist nun Eure Aufgabe Elementium zu finden. Ihr seid es, der die körperliche Form des Feuerfürsten zerstören muss.\n\nGewinnt dadurch den Segen von Donneraan.", sourceObjective = "Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 verzauberte Elementiumbarren und die Essenz des Feuerfürsten bringen.", progress = "Zwingt die Welt in die Knie, wenn es sein muss!", completion = "Selbst in meinen Träumen wagte ich es nicht diesen Tag vorherzusehen.\n\nSehet, Sterblicher.\n\nSEHET DEN, DER ÄLTER ALS ALLES EXISTIERENDE IST!\n\nSEHET DEN, DER SICH TITANEN UND GÖTTERGLEICHEN STELLTE!\n\nERHEBT EUCH MEISTER! BEFREIT EUCH VON EUREN FESSELN!", sourceObjectiveStatus = "unverified-source-field" }
quests[7787] = { id = 7787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerzorn erwache!", description = "Ihr habt den Windsucher bezwungen. Nehmt die schlummernde Klinge und die Materialen, die Ihr Demitrian für seinen Verrat geliefert habt, und zwingt den verlogenen Schuft, Donnerzorn zu erwecken.", sourceObjective = "Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge.", progress = "<Demitrian kauert in Eurer Gegenwart nieder.>", completion = "Ich flehe Euch an, verschont mich! Nehmt! Nehmt die Klinge! Lasst Demitrian sein erbärmliches Leben noch einmal neu angehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[7788] = { id = 7788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7789] = { id = 7789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche, unseren Fortschritt zu behindern, zunichtemacht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück, {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid, und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7790] = { id = 7790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Written Word" }
