quests[7810] = { id = 7810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Arena", description = "Es muss noch mehr dahinterstecken, ein Arenameister zu sein!\n\nVielleicht weiß der Pirat, der für die Veranstaltung in Gurubashi verantwortlich ist, mehr darüber!", sourceObjective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.\n\nBereitgestellter Gegenstand:", completion = "Aye, mein' Jung. Ein son' Schmuckstück is nich genuch, um Euch zum Meister der Arena zu machen! Jetz' is es an der Zeit, Euch richtig zu beweisen.", sourceObjectiveStatus = "unverified-source-field" }
