quests[7828] = { id = 7828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pirsch auf die Pirscher", description = "Viele mutige Trolle haben wir in der rauen Wildnis der Hinterlands verloren, {race}. Die Silbermähnenwölfe stellen eine der größten Bedrohungen für unsere Jäger dar. Sie lauern versteckt in den Büschen und schlagen zu, sobald sie eine Möglichkeit dazu sehen.\n\nDiese Art von Gewalt wird nicht länger geduldet!\n\nIhr müsst wie die Silbermähnen denken. Lauert den Pirschern auf! Tötet sie alle!", sourceObjective = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 5 Silbermähnenpirscher und 5 Silbermähnenheuler tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\n\nMarkhor erwähnte, dass sich die Wölfe in der Wildnis des Hinterlands verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[7829] = { id = 7829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Wilden", description = "Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Bruchhauer verloren wir an die grausamen Krallen und die Schnäbel der Biester.\n\nTötet jede wilde Eulenbestie, die Ihr finden könnt, {race}. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.", sourceObjective = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 10 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\n\nMarkhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[7830] = { id = 7830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefallenen rächen", description = "Dieser Abschaum namens Wildhammer trainiert Greifen, um Trolle abzuschlachten. Schrecklich, Ich weiß, aber sorgt Euch nicht denn ihnen wird bald Gerechtigkeit widerfahren.\n\nFür den Moment möchte ich, dass Ihr Euch auf die Ausrottung der Greifen in dieser Region konzentriert, die auch als Himmelsfürsten bekannt sind.\n\nTötet einen und bringt mir seinen Federbusch!", sourceObjective = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an Euch nehmt. Kehrt zu ihm zurück sobald Ihr diese Aufgabe erledigt habt.\n\nDie Klingenschnabelhimmelsfürsten sind eine recht seltene Spezies und nisten meist in der Wildnis des Hinterlands.", sourceObjectiveStatus = "unverified-source-field" }
