quests[7837] = { id = 7837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Runenstoff" }
quests[7838] = { id = 7838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister der Arena", progress = "Aye, Landratte! Bringt mir 12 Schmuckstücke des hiesigen Meisters der Arena und Ihr seid der neue Großmeister der Arena der Gurabashi! Arrrr!", completion = "Ihr habt viel Blut in der Arena vergossen! Ich bin stolz darauf, Euch hiermit zum Großmeister der Arena zu ernennen!" }
quests[7839] = { id = 7839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schläger der Blutfratzen", description = "Der Blutfratzenabschaum ist in unser Dorf eingedrungen und hat mein Werkzeug gestohlen! Ich habe zwar Ersatz, aber das Set, das sie mir geraubt haben, war das Geschenk eines gutherzigen Gnoms, der mir als junger Orc das Leben gerettet hat.\n\nIch möchte dieses Werkzeug wieder haben, {name} - es bedeutet mir ungeheuer viel.\n\nMarkhor berichtete, dass die Werkzeuge nahe der Tempel von Agol'watha und Shaol'watha gesichtet wurden.\n\nDiese Tempel liegen im Nordosten des Hinterlands.\n\nFindet meine Werkzeuge!", sourceObjective = "Schmied Aschenbaum aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.\n\nIhr erinnert Euch an Schmied Aschenbaums Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Blutfratzen zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch den Lauerfels absuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7840] = { id = 7840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lards vergessene Brotzeit", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Blutfratzentroll Lard mit großem Stock geschlagen hat. Lard zurück ins Dorf der Bruchhauer gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", sourceObjective = "Lard aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Blutfratzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7841] = { id = 7841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft an die Wildhämmer", description = "Die Wildhämmer fangen Geschäfte mit unseren Feinden an, Mann, schmieden neue Bündnisse. Diesmal sind es die Hochelfen, Mann.\n\n<Otho spuckt.>\n\nWir werden diesen Wildhammerzwergen wohl 'ne Botschaft überbringen müssen - 'ne Botschaft geschrieben mit dem Blut unserer Feinde. Tötet alle Hochtalelfen, alle die Euch über den Weg laufen, klar? Un' lasst ihre Leichen als Warnung zurück.\n\nVerscherzt es Euch niemals mit den Trollen!", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 5 Hochtalkundschafterinnen, 8 Hochtalspäher, 2 Hochtalschützen und 5 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück.\n\nIhr findet die Hochtalelfen bei der Jagdhütte von Quel'Danil im Nordwesten des Hinterlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[7842] = { id = 7842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere Botschaft an die Wildhämmer", description = "Man sagt, dass die Wildhämmer den Greifen so nahe stehen wie die Trolle ihren Gefährten. Widerlich, aber wir können das zu unserem Vorteil nutzen, Mann. Wir senden ihnen eine weitere Botschaft.\n\nTötet alle Greifen, die Ihr im Hinterland seht und sammelt eine lange elegante Feder ein. Daraus machen wir dann die letzte Botschaft.", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr ihm 1 lange elegante Feder von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit der Feder zu ihm zurück.\n\nEs ist bekannt, dass Greifen überall im Hinterland zu finden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[7843] = { id = 7843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Botschaft an die Wildhämmer", description = "<Otho überreicht Euch einen langen, blutverschmierten Speer, den mehrere Greifenfedern umhüllen.>\n\nNehmt den hier, Mann. Geht damit zum Nistgipfel, zum toten Stadtzentrum beim Brunnen. Platziert ihn dort! Rammt ihn richtig in den Boden und zeigt diesen Zwergen, dass die Trolle es ernst meinen! Kommt danach zu mir zurück... hoffentlich noch in einem Stück.", sourceObjective = "Otho Moji'ko aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr zum Nistgipfel im Westen des Hinterlands reist und die letzte Botschaft an die Wildhämmer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück.\n\nHütet Euch vor zornigen Wildhammerzwergen und niederträchtigen Mitgliedern der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[7844] = { id = 7844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kannibalistische Vettern", description = "Drei verschiedene Trollstämme bewohnen das Hinterland, {name}. So viel zu den Gemeinsamkeiten der Stämme: Wir sind alle Trolle und wir leben im Hinterland.\n\nDie Blutfratzen sind eine verkommene Bande, die sich an anderen Trollen und Humanoiden nährt.\n\nWäre Zul'jin hier, hätte er sie alle mit einem einzigen Faustschlag niedergeschmettert - ach, Zul'jin ist noch immer nicht zurückgekehrt und wir sind uns selbst überlassen.\n\nEs liegt nun an Euch diese Gegend zu säubern!", sourceObjective = "Mystikerin Yayo'jin aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr 6 Skalpierer der Blutfratzen und 2 Sterndeuter der Blutfratzen tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück.\n\nYayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[7845] = { id = 7845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entführung des Ältesten Stumpfhauer", description = "Mein Gefährte wurde von den wilden Blutfratzen bei einem dreisten Überfall um Mitternacht verschleppt. Unsere Spione haben mir berichtet, dass er noch am Leben ist und hoch oben in Jintha'Alor gefangen gehalten wird. Man sagt, dass die üble Priesterin Hexx ihn als Opfer für den gesichtslosen Blutgott Hakkar vorbereiten lässt.\n\nIhr müsst ihn retten, {name}! Unser Dorf könnte einen so großen Verlust nicht verschmerzen.", sourceObjective = "Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr ihren Gefährten, den Ältesten Stumpfhauer, aus Jintha'Alor befreit.\n\nMan sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Blutfratzen im Süden des Hinterlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[7846] = { id = 7846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlangt den Schlüssel!", description = "Der Schlüssel zu meinen Fesseln ist im Besitz von Hitah'ya der Bewahrerin. Sie hält sich in der nahegelegenen Höhle auf. Seid vorsichtig, {class}, sie wird äußerst gut bewacht.\n\nTötet sie und bringt dann den Schlüssel zurück, um meine Fesseln zu öffnen. Erst dann werde ich frei und in der Lage sein, nach Hause zurückzukehren.", sourceObjective = "Der Älteste Stumpfhauer in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Ältesten Stumpfhauer zurück, wenn Ihr den Schlüssel habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7847] = { id = 7847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Ura Stumpfhauer", description = "Kehrt zu meiner Gefährtin Ura Stumpfhauer ins Dorf der Bruchhauer zurück. Richtet ihr aus, dass ich heimkehren werde! Sie wird Euch sicherlich belohnen.", sourceObjective = "Der Älteste Stumpfhauer in Jintha'Alor möchte, dass Ihr Ura Stumpfhauer im Dorf der Bruchhauer die Neuigkeit von seiner Befreiung überbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7848] = { id = 7848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung mit dem Kern", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, {race}. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Schwarzfels führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Schwarzfelstiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", sourceObjective = "Begebt Euch zum Portal in den Schwarzfelstiefen, das in den Geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter im Schwarzfels zurück.", progress = "Ihr müsst Eure Seele mit dem Geschmolzenen Kern abstimmen, bevor Ihr Zugang erhaltet.", completion = "Ich bin jetzt in der Lage, Euch zum Geschmolzenen Kern zu transportieren. Ihr braucht nur zu fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7849] = { id = 7849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die getrennten Brüder", description = "Wie viele in unserem Dorf, habe auch ich einen Nahestehenden verloren. Ach, es war mein Zwillingsbruder Malkhor - er wurde beim selben Überfall wie Stumpfhauers Gefährte von den Blutfratzen verschleppt.\n\nDas Schicksal sollte ihn traurigerweise nicht vom Tod verschonen und er wurde schnell und brutal hingerichtet. Seine Überreste wurden an die Schlamme und Wölfe der Blutfratzen verfüttert.\n\nWir können zwar nicht mehr sein Leben retten, aber es ist noch nicht zu spät, um seine Seele zu befreien. Bergt seine Überreste, {name}.", sourceObjective = "Jäger Markhor aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.\n\nMarkhor erwähnte, dass die Überreste seines Bruders an die Schlamme und Wölfe der Blutfratzen verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Schlammen gibt sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.", sourceObjectiveStatus = "unverified-source-field" }
quests[7850] = { id = 7850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Blutfratzen kämpfen mit übernatürlicher Wildheit. Dies liegt an der elenden Magie, die von der üblen Priesterin Hexx gewirkt wird.\n\nIhr werdet in ganz Jintha'Alor dunkle Gefäße mit besudeltem Blut finden. Die Gefäße verstrahlen die elende Magie des gesichtslosen Blutgottes, verleihen den Blutfratzen Macht und treiben sie zusätzlich in den Wahnsinn.\n\nStehlt diese Gefäße und bringt sie zu mir, damit ich sie von der Besudelung reinigen und letztendlich die Gewalt des Blutgottes zerschlagen kann.", sourceObjective = "Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland möchte, dass Ihr Euch 5 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Ura Stumpfhauer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7861] = { id = 7861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Üble Priesterin Hexx und ihre Diener", description = "Der üblen Priesterin Hexx und ihren Dienern soll im Namen von Ura Stumpfhauer Gerechtigkeit widerfahren!\n\nWer auch immer die üble Priesterin Hexx und alle ihre Aman'zasiwachen vernichten möge, soll eine bedeutende Entlohnung erhalten.", sourceObjective = "Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 5 Aman'zasiwachen der Blutfratzen zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Ura Stumpfhauer aus dem Dorf der Bruchhauer im Hinterland.\n\nDie üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[7862] = { id = 7862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offener Posten: Wachbefehlshaber der Bruchhauer", description = "Mit dem Verlust von Malkhor ist auch wieder der Posten des Wachbefehlshabers der Bruchhauer unbesetzt. Sollte es Euch interessieren Befehlshaber der Bruchhauerwachen zu werden, so erfüllt die folgenden Aufgaben und reicht Eure Bewerbung bei Ura Stumpfhauer ein:\n\nRottet die Berserker der Blutfratzen aus.\n\nRottet die Schattenjäger der Blutfratzen aus.\n\nRottet die Bluttrinker der Blutfratzen aus.\n\nRottet die Seelenfresser der Blutfratzen aus.", sourceObjective = "Ihr wurdet mit der Vernichtung von 5 Berserkern der Blutfratzen, 3 Schattenjägern der Blutfratzen, 3 Bluttrinkern der Blutfratzen und 2 Seelenfressern der Blutfratzen beauftragt.\n\nKehrt nach Beendigung dieser Aufgabe zu Ura Stumpfhauer ins Dorf der Bruchhauer im Hinterland zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7863] = { id = 7863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket der Schildwache" }
quests[7864] = { id = 7864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket der Schildwache" }
quests[7865] = { id = 7865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Schildwache" }
quests[7866] = { id = 7866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket der Vorhut", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Kriegshymnenschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7867] = { id = 7867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket der Vorhut" }
quests[7868] = { id = 7868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Vorhut", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Kriegshymnenschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[7871] = { id = 7871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7872] = { id = 7872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7873] = { id = 7873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7874] = { id = 7874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7875] = { id = 7875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche, unseren Fortschritt zu behindern, zunichtemacht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück, {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid, und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7876] = { id = 7876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[7877] = { id = 7877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[7881] = { id = 7881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktsstiefel" }
