quests[7903] = { id = 7903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Fledermausaugen" }
quests[7905] = { id = 7905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelmond-Jahrmarkt", description = "Der Dunkelmond-Jahrmarkt kommt! Nehmt an unseren aufregenden Spielen teil, gewinnt fabulöse Preise und erfahrt, wie es um Eure Zukunft steht!\n\nZögert nicht und Ihr werdet diesen Gutschein gegen kostenfreie Gewinnlose und einen der weltberühmten Abenteuerführer des Dunkelmond-Jahrmarkts einlösen können! Mit ihm werdet Ihr die Schätze, die Ihr auf Euren Reisen findet, leicht identifizieren können.\n\nBringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan befindet sich der Zugang zum Jahrmarkt außerhalb von Goldhain im Wald von Elwynn.", sourceObjective = "Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose und eine kostenlose Ausgabe des Abenteuerführers des Dunkelmond-Jahrmarkts!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Dank des praktischen Abenteuerführers werdet Ihr wertvolle Gegenstände leichter finden und wissen, ob sich Sammler auf unserem Markt dafür interessieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[7906] = { id = 7906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelmond-Karten: Bestien" }
quests[7907] = { id = 7907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestienkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Bestienkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Bestienkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, das Bestienkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[7908] = { id = 7908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Arena", description = "Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.", sourceObjective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Störtebrecher.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
