quests[7926] = { id = 7926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelmond-Jahrmarkt", description = "Der Dunkelmond-Jahrmarkt kommt! Nehmt an spannenden Spielen teil, gewinnt fabulöse Preise, lasst Euch Eure Zukunft deuten!\n\nZögert nicht und Ihr werdet diesen Gutschein gegen kostenfreie Gewinnlose und einen der weltberühmten Abenteuerführer des Dunkelmond-Jahrmarkts einlösen können! Mit ihm werdet Ihr die Schätze, die Ihr auf Euren Reisen findet, leicht identifizieren können.\n\nBringt Euren Gutschein einfach zu Gelvas Rußgatter, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan befindet sich der Zugang zum Jahrmarkt außerhalb von Donnerfels in Mulgore.", sourceObjective = "Bringt den Gutschein zu Gelvas Rußgatter, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose und eine kostenlose Ausgabe des Abenteuerführers des Dunkelmond-Jahrmarkts!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Dank des praktischen Abenteuerführers werdet Ihr wertvolle Gegenstände leichter finden und wissen, ob sich Sammler auf unserem Markt dafür interessieren!", sourceObjectiveStatus = "unverified-source-field" }
